function ledger(query=filter){const xs=ledgerView(state).filter(r=>[r.title,r.category,r.receipt,`${Number(r.date.slice(5,7))}月${Number(r.date.slice(-2))}日`].join(' ').includes(query));return `<div class="card" style="padding-top:4px;padding-bottom:4px">${xs.length?xs.map(r=>{const day=`${Number(r.date.slice(5,7))}月${Number(r.date.slice(-2))}日`,amount=(r.direction==='income'?'+':'−')+money(r.amountMinor/100);return `<button class="menu-row" data-action="bill" data-name="${esc(r.title)}" data-amount="${esc(amount)}" data-date="${day}" data-category="${esc(r.category)}" data-receipt="${esc(r.receipt||'')}" data-task="${esc(r.taskId||'')}" data-movement="${r.movement}"><span class="icon-box">${icon(r.icon)}</span><span class="grow"><strong>${esc(r.title)}</strong><small>${day} ${esc(r.category)}${r.movement==='principal'?' 本金划转':''}</small>${r.receipt?`<small>回执 ${esc(r.receipt)}</small>`:''}</span><span class="value ${r.direction==='income'?'positive':''}">${state.mask?'••••':amount}</span></button>`}).join(''):'<div class="empty">没有找到相关账单。</div>'}</div>`}

function charts(){const facts=financialFacts(state),denominator=facts.expenseMinor/100||1,icons={'住房':'home','餐饮':'receipt','购物':'wallet','订阅':'card','出行':'plane','人情往来':'user'};const cats=facts.categories.map(([name,amount])=>[name,amount/100,icons[name]||'spark']);category=Math.min(category,Math.max(0,cats.length-1));const colors=Array.from({length:7},(_,i)=>`var(--chart-${i+1})`);let angle=-90;const polar=(deg,r)=>[100+Math.cos(deg*Math.PI/180)*r,100+Math.sin(deg*Math.PI/180)*r];const sectors=cats.map(([name,amount],i)=>{let end=angle+amount/denominator*360;const a=polar(angle,80),b=polar(end,80),c=polar(end,56),d=polar(angle,56),mid=(angle+end)/2;const tx=i===category?Math.cos(mid*Math.PI/180)*5:0,ty=i===category?Math.sin(mid*Math.PI/180)*5:0;const path=`M${a}A80 80 0 ${end-angle>180?1:0} 1 ${b}L${c}A56 56 0 ${end-angle>180?1:0} 0 ${d}Z`;angle=end;return `<g transform="translate(${tx} ${ty})" ><path d="${path}" fill="${colors[i%colors.length]}" stroke="none" data-action="category" data-index="${i}" role="button" tabindex="0" aria-label="选择${name}"/></g>`}).join('');const selected=cats[category];const vals=facts.days.map(n=>n/100);const x=i=>10+i*10,y=v=>120-v/(Math.ceil(denominator/1000)*1000||1000)*105;const line=vals.map((v,i)=>`${i?'L':'M'}${x(i)} ${y(v)}`).join(' ');return `<div class="card"><div class="row between"><h3>支出构成</h3><small>11月 截至2日</small></div><svg class="interactive-donut" viewBox="0 0 200 200" role="img" aria-label="支出分类，选中${selected[0]}">${sectors}<g transform="translate(89 89)" class="center-category">${icon(selected[2])}</g></svg><button class="category-capsule full" data-action="category-detail" data-category="${selected[0]}"><span>${selected[0]} <small>${(selected[1]/denominator*100).toFixed(1)}%</small></span><strong>${money(selected[1])}</strong>${icon('arrow')}</button><div class="category-selector" style="margin-top:12px">${cats.map(([t,a],i)=>button(`<span>${t}</span><strong>${money(a)}</strong>`,'category','',`data-index="${i}" aria-pressed="${i===category}"`)).join('')}</div></div><div class="spacer"></div><div class="card"><h3>累计支出</h3><div class="big money" style="margin-top:12px">${money(vals[trend])}</div><svg viewBox="0 0 310 145" class="chart" role="img" aria-label="累计支出趋势，选中11月${trend+1}日"><path d="${line}"/><path stroke-dasharray="3 4" stroke-width="1" d="M${x(trend)} 8V124"/><circle cx="${x(trend)}" cy="${y(vals[trend])}" r="4" fill="var(--solid)" stroke="var(--white)"/>${vals.map((v,i)=>`<rect x="${x(i)-5}" y="0" width="10" height="125" fill="transparent" stroke="none" role="button" tabindex="0" aria-label="选择11月${i+1}日" data-action="trend-point" data-index="${i}"/>`).join('')}</svg><div class="chart-axis"><span>11月1日</span><span>11月30日</span></div><input class="trend-point" type="range" min="0" max="29" value="${trend}" id="trend" aria-label="选择趋势日期"><small>11月${trend+1}日 ${money(vals[trend])}</small>${button('查看当天明细','day-detail','quiet full',`data-day="${trend+1}"`)}</div>`}

